        constexpr float kQuarter = 1.5707963f;
        constexpr float kRoofPitch = 0.7853982f;       // 45 degrees

        Vec3 Cross(Vec3 a, Vec3 b) { return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x}; }

        // A wall-like piece's snap points: its four corners and the middles of its top and bottom.
        std::vector<Vec3> EdgeSnaps(float halfWidth, float height)
        {
            return {{0, -halfWidth, 0}, {0, halfWidth, 0}, {0, 0, 0},
                    {0, -halfWidth, height}, {0, halfWidth, height}, {0, 0, height}};
        }

        // A floor's: its top's corners and edge middles.
        std::vector<Vec3> FloorSnaps(float half, float top)
        {
            return {{-half, -half, top}, {-half, half, top}, {half, -half, top}, {half, half, top},
                    {half, 0, top}, {-half, 0, top}, {0, half, top}, {0, -half, top}};
        }

